css_rules:
:root { --vh: 1vh; --default-font: "Britti Sans"; --header-font: "Feature Display"; --ref-screen-width: 1440; --site-padding-x: min(60px, calc(40 * 100vw / var(--ref-screen-width))); --site-padding-y: var(--site-padding-x); --color-white: #fbfff4; --color-dark-green: #203727; --color-light-green: #e0ffab; --content-width: calc(100vw - var(--site-padding-x) * 2); --content-unit: calc(var(--content-width) / var(--ref-screen-width)); --h2: max(65px, calc(var(--content-unit) * 110)); --body2: max(14px, calc(var(--content-unit) * 16)); --btn1: max(16px, calc(var(--content-unit) * 16)); }
h2 { font-family:var(--header-font);font-weight:200;margin:0;padding:0;line-height:1 }
h2 { font-size:var(--h2) }
.body2 { font-family:var(--default-font);font-weight:400;font-size:var(--body2) }
.button { font-family:var(--default-font);font-weight:600;font-size:var(--btn1) }
@font-face { font-family:Feature Display;font-weight:200;font-style:normal;font-display:block;src:url(/assets/fonts/FeatureDisplay-Extralight.woff2) format("woff2") }
@font-face { font-family:Feature Display;font-weight:400;font-style:normal;font-display:block;src:url(/assets/fonts/FeatureDisplay-Regular.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:400;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Regular.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:300;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Light.woff2) format("woff2") }
@font-face { font-family:Britti Sans;font-weight:600;font-style:normal;font-display:block;src:url(/assets/fonts/BrittiSans-Semibold.woff2) format("woff2") }
html { width:100%;height:100%;color:var(--color-white);line-height:1.4 }
body { position:fixed;width:100%;height:100%;overflow:hidden;margin:0;overscroll-behavior:none;touch-action:none }
* { box-sizing:border-box }
section { position:relative;width:100% }
.button { position:relative;display:flex;width:-moz-fit-content;width:fit-content;align-items:center;gap:.8em;height:3em;padding:.4em .4em .4em 1.5em;border-radius:1.5em;cursor:pointer;color:var(--color-dark-green);transition:color .25s ease-in-out;cursor:default }
.button span { position:relative;height:1.25em;transition:opacity .25s ease-out,transform .25s ease-out }
.button span:nth-child(1) { opacity:1 }
.button span:nth-child(2) { position:absolute;margin-left:-.5ex;opacity:0;transform:translateY(1em) }
.button:hover span:nth-child(1) { opacity:0;transform:translateY(-1em) }
.button:hover span:nth-child(2) { opacity:1;transform:translateY(0) }
.button svg { position:relative;display:flex;height:100%;fill:var(--color-dark-green) }
.button:before { content:"";position:absolute;inset:0;border-radius:1.5em;background:var(--color-light-green);transition:transform .25s ease-in-out,background .25s ease-in-out,box-shadow .25s ease-in-out }
.button:hover:before { transform:scale(.97) }
#home-pool { padding-bottom:calc(var(--vh) * 200) }
#home-pool .section__content { height:calc(var(--vh) * 100);pointer-events:none }
#home-pool .content-inner { width:100%;height:calc(var(--vh) * 100);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1em;perspective:600px;transform-style:preserve-3d }
#home-pool .title-wrapper { transform-style:preserve-3d;pointer-events:auto }
#home-pool .title { text-shadow:0 0 .12em rgba(0,0,0,.3);display:flex;flex-direction:column;align-items:center;justify-content:center }
#home-pool .title { transform-style:preserve-3d }
#home-pool .description { text-shadow:0 0 1em rgba(0,0,0,.3);max-width:52ch;text-align:center;transform-style:preserve-3d;pointer-events:auto }
#home-pool__cta { --width: 0px;transform-origin:50% 50%;pointer-events:auto }
#home-pool__cta:before { inset:0 }
.section { position:relative }
.section__content { position:relative;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:var(--site-padding-y) var(--site-padding-x) }
.title-wrapper { width:100%;display:flex;flex-direction:column;align-items:flex-start;gap:1em;justify-content:center;align-items:center }
.title { text-shadow:0 0 .12em rgba(0,0,0,.3) }
.description { text-shadow:0 0 1em rgba(0,0,0,.3) }
@media (max-width: 991.98px) {
#home-pool .title { text-align:center }
#home-pool .description { max-width:38ch }
}
